NAME = 'FinBiblia: Finnish Biblia (1776)'
BOOK = 'Prayer of Azariah'

CHAPTERS = {
    1: {
        1: 'Ja Asaria seisoi keskellä tulista pätsiä, avasi suunsa, rukoili ja sanoi:',
        2: 'Ole kiitetty Herra, meidän isäimme Jumala, ja sinun nimes olkoon ylistetty ja kunnioitettu ijankaikkisesti.',
        3: 'Sillä sinä olet hurskas kaikissa, mitä sinä meille tehnyt olet; kaikki sinun työs ovat totiset, ja mitä sinä teet, se on oikia, ja kaikki sinun tuomios ovat laittamattomat.',
        4: 'Sinä teet meille oikein, ettäs meitä rangaissut olet senkaltaisella rangaistuksella, jonka sinä meidän päällemme olet antanut tulla, ja Jerusalemin, meidän isäimme pyhän kaupungin päälle; tosin sinä teet siinä oikein meidän synteimme tähden. 29, Sillä me olemme syntiä ja pahoin tehneet, että me sinusta luopuneet olemme ja joka paikassa tehneet sinua vastaan.',
        5: 'Emme myös ole totelleet sinun käskyjäs, emmekä niistä lukua pitäneet, että me olisimme tehneet niiden jälkeen, niinkuin sinä meille käskenyt olit, että me menestyisimme.',
        6: 'Sentähden olet sinä oikein tehnyt, ettäs ne kaikki olet antanut tulla meidän päällemme,',
        7: 'Ja antanut meitä vihollistemme, jumalattomain ja pahain ihmisten, ja väärän ja julmimman: kuninkaan käsiin maan päällä.',
        8: 'Ja emme rohkene suutamme avata: niin me olemme häpiän ja naurun alaiseksi tulleet sinun palveliais edessä ja kaikkein niiden edessä, jotka sinua pelkäävät.',
        9: 'Mutta älä kuitenkaan meitä peräti hylkää, sinun pyhän nimes tähden, ja älä heitä pois sinun liittoas.',
        10: 'Ja älä ota laupiuttas meiltä pois, Abrahamin, rakkaan ystäväs; tähden, ja sinun palvelias Isaakin, ja Israelin sinun pyhäs tähden,',
        11: 'Joille sinä olet luvannut heidän siemenensä lisätä niinkuin tähdet taivaassa ja sannan meressä.',
        12: 'Sillä me olemme halvemmaksi tulleet kaikkia pakanoita ja olemme nyt kaikkein suurimmasti ylönkatsotut maan päällä, meidän synteimme tähden,',
        13: 'Ettei meillä yhtään ruhtinasta, prophetaa eikä opettajaa ole, ei polttouhria eikä jokapäiväistä uhria, ei ruokauhria eikä suitsutusta, ei myös ole yhtään paikkaa, kussa me sinun edessäs uhraisimme ja löytäisimme armon;',
        14: 'Vaan särjetyllä sydämellä ja murheellisella hengellä tulemme me sinun etees, niinkuin me toisimme polttouhria oinaista ja mulleista, ja monta tuhatta lihavaa lammasta.',
        15: 'Niin anna meidän uhrimme tänäpänä sinulle kelvata ja otolliset olla; sillä et sinä anna niitä häpiään tulla, jotka sinun päälles toivovat.',
        16: 'Näin tulemme me nyt kaikella sydämellä ja etsimme sinun kasvojas pelvolla.',
        17: 'Sen tähden älä anna meidän häpiään tulla, vaan tee meille, Herra, sinun armos ja suuren laupiutes jälkeen,',
        18: 'Ja kirvota meitä sinun ihmeellisten tekois perästä, ja anna sinun nimelles kunnia:',
        19: 'Että ne häpeäisivät, jotka sinun palvelioilles pahaa tekevät, ja häpiään tulisivat sinun suuren voimas edessä, että heidän voimansa kukistetuksi tulis;',
        20: 'Että he ymmärtäisivät sinun olevan Herran ainoan Jumalan, suuressa kunniassa maanpiirin päällä.',
        21: 'Ja kuninkaan palveliat, jotka heidät pätsiin heittäneet olivat, ei lakanneet, vaan heittivät lakkaamatta tulikiveä, pikiä, rohtimia ja kuivia varpuja,',
        22: 'Että liekki löi pätsistä yhdeksänviidettäkymmentä kyynärää korkialle,',
        23: 'Ja kulutti ympäriltänsä ja poltti Kaldealaiset, joihinka se ulottui, pätsin edessä.',
        24: 'Mutta Herran enkeli käveli heidän kanssansa, jotka Asarian tykönä pätsissä olivat,',
        25: 'Ja ajoi ulos tulen liekin pätsistä, ja teki pätsissä niinkuin kylmän kasteen, ettei tuli ensinkään heihin sattunut eikä polttanut eli vahingoittanut heitä.',
        26: 'Silloin rupesivat ne kolme toinen toisensa kanssa veisaamaan, kiittivät ja ylistivät Jumalaa pätsissä, ja sanoivat:',
        27: 'Kiitetty ole sinä, Herra, meidän isäimme Jumala! ja sinua pitää kiitettämän ja ylistettämän ijankaikkisesti. Kiitetty olkoon sinun kunniallinen ja pyhä nimes, ja se pitää kiitetty ja ylistetty oleman ijankaikkisesti.',
        28: 'Kiitetty ole sinä sinun pyhässä ja kuuluisassa templissäs, ja sinun pitää kiitetyn ja ylistetyn oleman ijankaikkisesti.',
        29: 'Kiitetty ole sinä, joka istut Kerubimin päällä ja näet syvyyteen, ja sinua pitää kiitettämän ja ylistettämän ijankaikkisesti.',
        30: 'Kiitetty ole sinä sinun kunniallisella kuninkaallisella istuimellas, ja sinua pitää kiitettämän ja ylistettämän ijankaikkisesti.',
        31: 'Kiitetty ole sinä taivaan vahvuudessa, ja sinua pitää kiitettämän ja ylistettämän ijankaikkisesti.',
        32: 'Kiittäkään Herraa kaikki hänen työnsä, ja niiden pitää häntä kunnioittaman ja ylistämän ijankaikkisesti.',
        33: 'Te taivaat, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        34: 'Kiittäkäät Herraa, te Herran enkelit, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        35: 'Kaikki vedet taivasten päällä, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        36: 'Kaikki Herran sotajoukko, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        37: 'Aurinko ja kuu, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        38: 'Kaikki tähdet taivaassa, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        39: 'Sade ja kaste, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        40: 'Kaikki tuulet, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        41: 'Tuli ja palavuus, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti. 67, Räntä ja rakeet, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        42: 'Päivä ja yö, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        43: 'Vaikeus ja pimeys, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        44: 'Jää ja pakkanen, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        45: 'Härmä ja lumi, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        46: 'Pitkäisen leimaus ja pilvet, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        47: 'Maa kiittäkään Herraa, kunnioittakaan ja ylistäkään häntä ijankaikkisesti.',
        48: 'Vuoret ja kukkulat., kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        49: 'Kaikki, mitä maan päällä kasvaa, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        50: 'Lähteet kiittäkään Herraa, kunnioittakaan ja ylistäkään häntä ijankaikkisesti.',
        51: 'Meret ja virrat, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        52: 'Valaskalat ja kaikki, kuin vesissä liikkuu, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä 79. Kaikki linnut taivaan alla, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        53: 'Kaikki metsän pedot ja eläimet, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        54: 'Te ihmisten lapset, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        55: 'Israel kiittäkään Herraa, kunnioittakaan ja ylistäkään häntä ijankaikkisesti.',
        56: 'Te Herran papit, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        57: 'Te Herran palveliat, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        58: 'Te vanhurskasten henget ja sielut, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        59: 'Te pyhät, jotka raadolliset ja murheelliset olette, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        60: 'Anania, Asaria ja Misael, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.',
        61: 'Sillä hän on meitä helvetistä pelastanut ja auttanut meitä kuolemasta,',
        62: 'Ja on pelastanut meidät tulisesta pätsistä, ja on meidät tulen keskellä varjellut.',
        63: 'Kiittäkäät Herraa; sillä hän on hyvä ja hänen hyvyytensä pysyy ijankaikkiseen.',
        64: 'Kaikki, jotka Herraa pelkäävät, kiittäkään kaikkein jumalten Jumalaa, kunnioittakaat ja ylistäkäät, että hänen hyvyytensä pysyy ijankaikkiseen.',
    },
}
